/**
 * scripts/make_corpus.js
 *
 * Produces verification corpus for Rogue 2048:
 * (a) At least 30 REAL UI runs with real touch swipes and taps under DEFAULT cadence
 *     (no ?first/?draft/?stones overrides, no debug injection), played by a driver with
 *     a corner/greedy policy until game over, including Rewind chains, Diagonal, Eraser,
 *     Mason, and Last Stand.
 * (b) At least 5 long runs (>= 1500 moves) generated by driving GameController in Node
 *     with sim bots and all relics, serialized in the exact same runLog shape and event format.
 *
 * Saves corpus to scripts/out/corpus/ (gitignored) and writes 3 small fixtures:
 *   - verify/fixtures/fixture_rewind.json
 *   - verify/fixtures/fixture_mason.json
 *   - verify/fixtures/fixture_last_stand.json
 */

import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

import { findChrome } from './find_chrome.js';
import { GameController } from '../game/controller.js';
import { createBot, chooseStoneCell } from '../sim/bots.js';
import { RELIC_IDS } from '../sim/relics.js';
import { verifyRun } from '../verify/verify_run.js';
import { computeEngineHash } from '../verify/cli.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');
const distDir = path.join(rootDir, 'dist');
const corpusDir = path.join(rootDir, 'scripts', 'out', 'corpus');
const fixturesDir = path.join(rootDir, 'verify', 'fixtures');

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

function startStaticServer() {
  const MIME_TYPES = {
    '.html': 'text/html; charset=utf-8',
    '.js': 'text/javascript; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.svg': 'image/svg+xml',
    '.png': 'image/png',
    '.woff2': 'font/woff2',
  };

  const server = http.createServer((req, res) => {
    const parsedUrl = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
    let pathname = decodeURIComponent(parsedUrl.pathname);
    let relPath = pathname.replace(/^\/+/, '');
    let filePath = path.join(distDir, relPath === '' ? 'index.html' : relPath);

    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end(`404 Not Found: ${pathname}`);
      return;
    }

    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, {
      'Content-Type': MIME_TYPES[ext] || 'application/octet-stream',
      'Cache-Control': 'no-cache',
    });
    fs.createReadStream(filePath).pipe(res);
  });

  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      resolve(server);
    });
  });
}

async function getFreePort() {
  const s = http.createServer();
  return new Promise((resolve) => {
    s.listen(0, '127.0.0.1', () => {
      const port = s.address().port;
      s.close(() => resolve(port));
    });
  });
}

async function getWsUrl(cdpPort) {
  for (let i = 0; i < 40; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${cdpPort}/json`);
      if (res.ok) {
        const list = await res.json();
        const page = list.find(t => t.type === 'page');
        if (page && page.webSocketDebuggerUrl) {
          return page.webSocketDebuggerUrl;
        }
      }
    } catch {}
    await sleep(200);
  }
  throw new Error('Could not connect to Chrome CDP');
}

class CdpClient {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 1;
    this.callbacks = new Map();

    this.ready = new Promise((resolve, reject) => {
      this.ws.onopen = resolve;
      this.ws.onerror = reject;
    });

    this.ws.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.id && this.callbacks.has(data.id)) {
        const { resolve, reject } = this.callbacks.get(data.id);
        this.callbacks.delete(data.id);
        if (data.error) reject(data.error);
        else resolve(data.result);
      }
    };
  }

  send(method, params = {}) {
    const id = this.id++;
    return new Promise((resolve, reject) => {
      this.callbacks.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async eval(expression) {
    const res = await this.send('Runtime.evaluate', {
      expression,
      returnByValue: true,
      awaitPromise: true,
    });
    if (res.exceptionDetails) {
      throw new Error(`Eval error: ${JSON.stringify(res.exceptionDetails)}`);
    }
    return res.result?.value;
  }

  close() {
    try { this.ws.close(); } catch {}
  }
}

/**
 * Plays a single real UI run in headless Chrome under DEFAULT cadence.
 */
async function playRealUiRun(cdp, baseUrl, runIndex, targetRelicFocus = null) {
  // Navigate to fresh root without query overrides
  await cdp.send('Page.navigate', { url: baseUrl });
  await sleep(250);

  // Click START
  await cdp.eval(`
    (() => {
      const btn = document.getElementById('btn-play-start');
      if (btn) btn.click();
    })()
  `);
  await sleep(100);

  let rewindChainExecuted = false;
  let diagonalUsed = false;
  let eraserUsed = false;
  let masonUsed = false;
  let moves = 0;
  const maxMoves = 1500;

  while (moves < maxMoves) {
    const isGameOver = await cdp.eval(`Boolean(window.controller && window.controller.isGameOver())`);
    if (isGameOver) {
      break;
    }

    // Step execution within browser
    const stepAction = await cdp.eval(`
      (async () => {
        const ctrl = window.controller;
        if (!ctrl) return { action: 'wait' };

        // 1. Pending decisions
        if (ctrl.hasPendingDecision()) {
          const dec = ctrl.getPendingDecision();
          if (dec.type === 'draft') {
            const draftOverlay = document.getElementById('draft-overlay');
            if (!draftOverlay || draftOverlay.classList.contains('hidden')) {
              return { action: 'wait_draft_modal' };
            }
            const offers = dec.offers || [];
            const priority = ['rewind', 'diagonal_charge', 'eraser', 'mason', 'last_stand'];
            if ('${targetRelicFocus}') {
              priority.unshift('${targetRelicFocus}');
            }
            let choice = offers[0];
            let choiceIdx = 0;
            for (const p of priority) {
              const idx = offers.indexOf(p);
              if (idx !== -1) {
                choice = p;
                choiceIdx = idx;
                break;
              }
            }
            const row = document.getElementById('draft-offers-row');
            const cards = row ? Array.from(row.querySelectorAll('.draft-card, .draftcard')) : [];
            if (cards.length > choiceIdx && cards[choiceIdx]) {
              cards[choiceIdx].click();
            } else if (cards.length > 0) {
              cards[0].click();
            }
            return { action: 'draft', choice };
          } else if (dec.type === 'mason') {
            const board = document.getElementById('game-board');
            if (!board || !board.classList.contains('draftdim')) {
              return { action: 'wait_mason_modal' };
            }
            const chosen = dec.candidates[0];
            const cell = document.querySelector('.cell[data-index=\"' + chosen + '\"], .grid-cell[data-index=\"' + chosen + '\"]');
            if (cell) cell.click();
            return { action: 'mason', chosen };
          }
        }

        // 2. Ability triggering
        // Rewind chain: if rewind has >= 2 charges and moves > 8, execute 2 consecutive rewinds
        const abState = ctrl.getAbilityState();
        const rwLevels = ctrl.getRewindUndoLevels ? ctrl.getRewindUndoLevels() : 0;
        if (!${rewindChainExecuted} && rwLevels >= 2 && ctrl.state.moveCount >= 8) {
          const rwBtn = document.querySelector('button.ability-btn[data-relic=\"rewind\"]');
          if (rwBtn && !rwBtn.disabled) {
            rwBtn.click();
            return { action: 'rewind_chain_1' };
          }
        }

        // Diagonal ability
        if (!${diagonalUsed} && abState.diagonal_charge && abState.diagonal_charge.charges > 0) {
          const targets = ctrl.getLegalTargets('diagonal_charge');
          if (targets && targets.length > 0) {
            const t = targets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"diagonal_charge\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const fromCell = document.querySelector('.cell[data-index=\"' + t.from + '\"], .tile[data-index=\"' + t.from + '\"]');
              const toCell = document.querySelector('.cell[data-index=\"' + t.to + '\"], .tile[data-index=\"' + t.to + '\"]');
              if (fromCell) fromCell.click();
              if (toCell) toCell.click();
              return { action: 'diagonal', target: t };
            }
          }
        }

        // Eraser ability
        if (!${eraserUsed} && abState.eraser && abState.eraser.charges > 0) {
          const targets = ctrl.getLegalTargets('eraser');
          if (targets && targets.length > 0) {
            const t = targets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"eraser\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const cell = document.querySelector('.cell[data-index=\"' + t.cell + '\"], .tile[data-index=\"' + t.cell + '\"]');
              if (cell) cell.click();
              return { action: 'eraser', cell: t.cell };
            }
          }
        }

        // Emergency rescue when stuck
        if (ctrl.state.stuckNeedsAbility) {
          if (rwLevels > 0) {
            const rwBtn = document.querySelector('button.ability-btn[data-relic=\"rewind\"]');
            if (rwBtn && !rwBtn.disabled) {
              rwBtn.click();
              return { action: 'rewind_rescue' };
            }
          }
          const diagTargets = ctrl.getLegalTargets('diagonal_charge');
          if (diagTargets.length > 0 && abState.diagonal_charge?.charges > 0) {
            const t = diagTargets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"diagonal_charge\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const fc = document.querySelector('.cell[data-index=\"' + t.from + '\"], .tile[data-index=\"' + t.from + '\"]');
              const tc = document.querySelector('.cell[data-index=\"' + t.to + '\"], .tile[data-index=\"' + t.to + '\"]');
              if (fc) fc.click();
              if (tc) tc.click();
              return { action: 'diagonal_rescue' };
            }
          }
          const eraseTargets = ctrl.getLegalTargets('eraser');
          if (eraseTargets.length > 0 && abState.eraser?.charges > 0) {
            const t = eraseTargets[0];
            const btn = document.querySelector('button.ability-btn[data-relic=\"eraser\"]');
            if (btn && !btn.disabled) {
              btn.click();
              const c = document.querySelector('.cell[data-index=\"' + t.cell + '\"], .tile[data-index=\"' + t.cell + '\"]');
              if (c) c.click();
              return { action: 'eraser_rescue' };
            }
          }
        }

        // 3. Normal touch swipe with corner/greedy policy
        const valid = ctrl.getValidMoves();
        if (valid.length === 0) {
          return { action: 'no_moves' };
        }

        const priority = ['D', 'L', 'R', 'U'];
        const dir = priority.find(d => valid.includes(d)) || valid[0];

        const board = document.getElementById('game-board');
        if (!board) return { action: 'no_board' };
        const rect = board.getBoundingClientRect();
        const startX = rect.left + rect.width / 2;
        const startY = rect.top + rect.height / 2;
        let endX = startX;
        let endY = startY;
        if (dir === 'L') endX -= 60;
        else if (dir === 'R') endX += 60;
        else if (dir === 'U') endY -= 60;
        else if (dir === 'D') endY += 60;

        const touchStart = new Touch({ identifier: Date.now(), target: board, clientX: startX, clientY: startY });
        const touchEnd = new Touch({ identifier: Date.now(), target: board, clientX: endX, clientY: endY });

        board.dispatchEvent(new TouchEvent('touchstart', { touches: [touchStart], changedTouches: [touchStart], bubbles: true }));
        board.dispatchEvent(new TouchEvent('touchend', { touches: [], changedTouches: [touchEnd], bubbles: true }));

        return { action: 'swipe', dir };
      })()
    `);

    if (stepAction.action === 'rewind_chain_1') {
      await sleep(35);
      // Execute 2nd rewind of the chain
      await cdp.eval(`
        (() => {
          const rwBtn = document.querySelector('button.ability-btn[data-relic=\"rewind\"]');
          if (rwBtn && !rwBtn.disabled) rwBtn.click();
        })()
      `);
      rewindChainExecuted = true;
    } else if (stepAction.action === 'diagonal') {
      diagonalUsed = true;
    } else if (stepAction.action === 'eraser') {
      eraserUsed = true;
    } else if (stepAction.action === 'mason') {
      masonUsed = true;
    }

    moves++;
    await sleep(20);
  }

  const runLog = await cdp.eval(`window.controller.getRunLog()`);
  return {
    runLog,
    usedRewindChain: rewindChainExecuted,
    usedDiagonal: diagonalUsed,
    usedEraser: eraserUsed,
    usedMason: masonUsed,
    usedLastStand: Boolean(runLog.lastStandFired),
  };
}

/**
 * Generates a long run (>= 1500 moves) in Node using GameController and bots.
 */
function generateLongRun(seed) {
  const bot = createBot('corner');
  const ctrl = new GameController(seed, {
    forcedRelics: RELIC_IDS.filter(r => r !== 'anchor_row'),
    shatterMin: 32,
    siphonMin: 16,
    stoneLifetime: 15,
    hazardSchedule: [{ upToMove: Infinity, interval: 35 }],
    moveCap: 5000,
  });

  let loopCount = 0;
  while (!ctrl.isGameOver() && ctrl.state.moveCount < 3000 && loopCount < 15000) {
    loopCount++;
    if (ctrl.hasPendingDecision()) {
      const dec = ctrl.getPendingDecision();
      if (dec.type === 'draft') {
        ctrl.resolveDecision(dec.offers[0]);
      } else if (dec.type === 'mason') {
        ctrl.resolveDecision(chooseStoneCell(ctrl.state, dec.candidates));
      }
      continue;
    }

    const dir = bot.chooseMove(ctrl.state);
    if (!dir) {
      // Stuck rescue with abilities
      const diag = ctrl.getLegalTargets('diagonal_charge');
      if (diag.length > 0 && (ctrl.state.abilities?.diagonal_charge?.charges || 0) > 0) {
        ctrl.useAbility('diagonal_charge', diag[0]);
        continue;
      }
      const erase = ctrl.getLegalTargets('eraser');
      if (erase.length > 0 && (ctrl.state.abilities?.eraser?.charges || 0) > 0) {
        ctrl.useAbility('eraser', erase[0]);
        continue;
      }
      if (ctrl.getRewindUndoLevels() > 0) {
        ctrl.useAbility('rewind', null);
        continue;
      }
      break;
    }

    ctrl.recordInput('swipe', dir);
    ctrl.submitMove(dir);
  }

  return ctrl.getRunLog();
}

async function main() {
  console.log('=== Rogue 2048: Generating Verification Corpus ===\n');

  if (!fs.existsSync(corpusDir)) fs.mkdirSync(corpusDir, { recursive: true });
  if (!fs.existsSync(fixturesDir)) fs.mkdirSync(fixturesDir, { recursive: true });

  const expectedHash = computeEngineHash();
  console.log(`Rules Engine SHA-256: ${expectedHash}`);

  // 1. Generate 30+ REAL UI runs in headless Chrome
  console.log('\n--- Part (a): Generating >= 30 Real UI Runs (DEFAULT Cadence) ---');
  const chromePath = findChrome();
  if (!chromePath) {
    throw new Error('Chrome/Chromium binary not found.');
  }

  const server = await startStaticServer();
  const serverPort = server.address().port;
  const baseUrl = `http://127.0.0.1:${serverPort}/`;

  const cdpPort = await getFreePort();
  const chromeProcess = spawn(chromePath, [
    `--remote-debugging-port=${cdpPort}`,
    '--headless=new',
    '--disable-gpu',
    '--no-sandbox',
    'about:blank',
  ]);

  const wsUrl = await getWsUrl(cdpPort);
  const cdp = new CdpClient(wsUrl);
  await cdp.ready;

  await cdp.send('Page.enable');
  await cdp.send('Runtime.enable');
  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width: 390,
    height: 844,
    deviceScaleFactor: 1,
    mobile: true,
  });

  const uiRuns = [];
  const focusRelics = ['rewind', 'mason', 'diagonal_charge', 'eraser', 'last_stand'];
  let runIdx = 1;

  let totalRewindChains = 0;
  let totalDiagonal = 0;
  let totalEraser = 0;
  let totalMason = 0;
  let totalLastStand = 0;

  let rewindFixture = null;
  let masonFixture = null;
  let lastStandFixture = null;

  while (uiRuns.length < 30 || totalRewindChains === 0 || totalDiagonal === 0 || totalEraser === 0 || totalMason === 0 || totalLastStand === 0) {
    const focus = focusRelics[(runIdx - 1) % focusRelics.length];
    process.stdout.write(`  [UI Run ${String(runIdx).padStart(2)}] Playing with focus: ${focus}... `);
    const result = await playRealUiRun(cdp, baseUrl, runIdx, focus);
    const log = result.runLog;

    const v = verifyRun(log, expectedHash);
    if (!v.ok) {
      console.log(`FAILED! (${v.status}: ${v.reason})`);
      throw new Error(`Real UI run ${runIdx} failed verification: ${v.reason}`);
    }

    if (result.usedRewindChain) totalRewindChains++;
    if (result.usedDiagonal) totalDiagonal++;
    if (result.usedEraser) totalEraser++;
    if (result.usedMason) totalMason++;
    if (result.usedLastStand) totalLastStand++;

    if (!rewindFixture && result.usedRewindChain) rewindFixture = log;
    if (!masonFixture && result.usedMason) masonFixture = log;
    if (!lastStandFixture && result.usedLastStand) lastStandFixture = log;

    uiRuns.push(log);
    const outName = `run_ui_${String(uiRuns.length).padStart(2, '0')}.json`;
    fs.writeFileSync(path.join(corpusDir, outName), JSON.stringify(log, null, 2), 'utf-8');

    console.log(`OK (moves: ${log.moveNumberAtDeath}, pts: ${log.points}, events: ${log.events.length}, ms: ${v.ms}ms)`);
    runIdx++;

    // Safety limit
    if (runIdx > 50) break;
  }

  cdp.close();
  chromeProcess.kill();
  server.close();

  console.log(`\n✔ Generated ${uiRuns.length} Real UI runs:`);
  console.log(`  - Runs using Rewind chains : ${totalRewindChains}`);
  console.log(`  - Runs using Diagonal      : ${totalDiagonal}`);
  console.log(`  - Runs using Eraser        : ${totalEraser}`);
  console.log(`  - Runs using Mason         : ${totalMason}`);
  console.log(`  - Runs using Last Stand    : ${totalLastStand}`);

  // Write the 3 committed fixtures
  if (rewindFixture) {
    fs.writeFileSync(path.join(fixturesDir, 'fixture_rewind.json'), JSON.stringify(rewindFixture, null, 2), 'utf-8');
    console.log(`✔ Saved verify/fixtures/fixture_rewind.json`);
  }
  if (masonFixture) {
    fs.writeFileSync(path.join(fixturesDir, 'fixture_mason.json'), JSON.stringify(masonFixture, null, 2), 'utf-8');
    console.log(`✔ Saved verify/fixtures/fixture_mason.json`);
  }
  if (lastStandFixture) {
    fs.writeFileSync(path.join(fixturesDir, 'fixture_last_stand.json'), JSON.stringify(lastStandFixture, null, 2), 'utf-8');
    console.log(`✔ Saved verify/fixtures/fixture_last_stand.json`);
  }

  // 2. Part (b): Generate at least 5 long runs (>= 1500 moves) in Node
  console.log('\n--- Part (b): Generating >= 5 Long Runs (>= 1500 moves) ---');
  const longSeeds = [207, 307, 407, 807, 1607];
  const longRuns = [];

  for (let i = 0; i < longSeeds.length; i++) {
    const seed = longSeeds[i];
    process.stdout.write(`  [Long Run ${i + 1}/5] Seed ${seed}... `);
    const log = generateLongRun(seed);
    const v = verifyRun(log, expectedHash);
    if (!v.ok) {
      console.log(`FAILED! (${v.reason})`);
      throw new Error(`Long run seed ${seed} failed verification: ${v.reason}`);
    }
    longRuns.push(log);
    const outName = `run_long_${String(i + 1).padStart(2, '0')}.json`;
    fs.writeFileSync(path.join(corpusDir, outName), JSON.stringify(log, null, 2), 'utf-8');
    console.log(`OK (moves: ${log.moveNumberAtDeath}, pts: ${log.points}, events: ${log.events.length}, ms: ${v.ms}ms)`);
  }

  console.log('\n✔ All corpus runs generated and verified successfully.');
}

const isMain = process.argv[1] && (
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url) ||
  path.resolve(process.argv[1]) === path.resolve(__filename)
);

if (isMain) {
  main().catch((err) => {
    console.error('❌ make_corpus failed:', err);
    process.exit(1);
  });
}
